PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, username TEXT NOT NULL UNIQUE COLLATE NOCASE, display_name TEXT NOT NULL, passhash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('reader','writer')), created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS novels (id INTEGER PRIMARY KEY, author_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, title TEXT NOT NULL, summary TEXT NOT NULL DEFAULT '', genre TEXT NOT NULL DEFAULT 'ทั่วไป', cover_color TEXT NOT NULL DEFAULT '#7453a8', published INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS chapters (id INTEGER PRIMARY KEY, novel_id INTEGER NOT NULL REFERENCES novels(id) ON DELETE CASCADE, title TEXT NOT NULL, body TEXT NOT NULL, position INTEGER NOT NULL, published INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, UNIQUE(novel_id,position));
CREATE TABLE IF NOT EXISTS shelves (user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, novel_id INTEGER NOT NULL REFERENCES novels(id) ON DELETE CASCADE, PRIMARY KEY(user_id,novel_id));
CREATE TABLE IF NOT EXISTS progress (user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, novel_id INTEGER NOT NULL REFERENCES novels(id) ON DELETE CASCADE, chapter_id INTEGER NOT NULL REFERENCES chapters(id) ON DELETE CASCADE, updated_at INTEGER NOT NULL, PRIMARY KEY(user_id,novel_id));
CREATE TABLE IF NOT EXISTS comments (id INTEGER PRIMARY KEY, chapter_id INTEGER NOT NULL REFERENCES chapters(id) ON DELETE CASCADE, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, body TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS ix_novels_public ON novels(published,updated_at);
CREATE INDEX IF NOT EXISTS ix_chapters_novel ON chapters(novel_id,position);
CREATE INDEX IF NOT EXISTS ix_sessions_expiry ON sessions(expires_at);
